(()=>{'use strict';const classes=window.DEX_INDEX,$=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const primitive={V:'void',Z:'boolean',B:'byte',S:'short',C:'char',I:'int',J:'long',F:'float',D:'double'},typ=d=>d.startsWith('[')?typ(d.slice(1))+'[]':primitive[d]||(d.startsWith('L')?d.slice(1,-1).replaceAll('/','.'):d);let selected=[],page=0,loaded='',loading=0;const size=40;
const flags=a=>[[1,'public'],[2,'private'],[4,'protected'],[8,'static'],[16,'final'],[64,'bridge'],[128,'varargs'],[256,'native'],[1024,'abstract'],[4096,'synthetic'],[65536,'constructor']].filter(([b])=>a&b).map(([,s])=>s).join(' ');
const domain=d=>d.startsWith('[')?'tablou; dimensiune și nulabilitate neconfirmate':({Z:'false | true',B:'int8: −128 .. 127',S:'int16: −32768 .. 32767',C:'unitate UTF-16: 0 .. 65535',I:'int32: −2147483648 .. 2147483647',J:'int64: −2^63 .. 2^63−1',F:'IEEE754 binary32',D:'IEEE754 binary64'}[d]||'referință obiect; nulabilitate neconfirmată');
function draw(){let a=selected.slice(page*size,(page+1)*size);$('#count').textContent=selected.length.toLocaleString('ro-RO')+' clase din '+classes.length.toLocaleString('ro-RO');$('#page').textContent=page+1;$('#prev').disabled=!page;$('#next').disabled=(page+1)*size>=selected.length;$('#results').innerHTML=a.map(c=>'<button class="result" data-fragment="'+c[1]+'"><strong>'+esc(c[0])+'</strong><small>'+c[2]+' metode · '+c[3]+' câmpuri · '+esc(c[4])+'</small></button>').join('');$('#results').querySelectorAll('button').forEach(b=>b.onclick=()=>{location.hash=b.dataset.fragment});}
function renderClass(c,fragment,methodIndex,paramIndex){let [name,dex,methods,fields,sup,interfaces]=c;const target=methodIndex!==undefined?methods[Number(methodIndex)]:null;let html='<span class="label">'+esc(dex)+'</span><h2>'+esc(name)+'</h2><p>'+methods.length+' metode · '+fields.length+' câmpuri</p><p class="note">Fișă structurală DEX. arg0, arg1… sunt poziții atribuite de catalog. Valorile, unitățile, validările și formatul pe fir nu rezultă din semnătură.</p><p>Superclasă: <code>'+esc(sup)+'</code><br>Interfețe: '+esc(interfaces.join(', '))+'</p>';
function method(m,i){const [mn,args,ret,access,codeOffset,kind,fid]=m,key=fragment+'/'+i;return '<section id="method-'+i+'"><h3><a href="#'+key+'">'+esc(mn)+'</a></h3><pre>'+esc(flags(access)+' '+typ(ret)+' '+mn+'('+args.map((d,j)=>typ(d)+' arg'+j).join(', ')+')')+'</pre><p><small>'+esc(fid)+' · codeOffset '+codeOffset+' · '+esc(kind)+'</small></p><table><thead><tr><th>Parametru</th><th>Tip / descriptor DEX</th><th>Clasă de valori</th></tr></thead><tbody>'+args.map((d,j)=>'<tr'+(String(j)===paramIndex?' class="note"':'')+'><td><a href="#'+key+'/'+j+'">arg'+j+'</a><br><small>'+esc(fid+'-p'+j)+'</small></td><td>'+esc(typ(d))+'<br><code>'+esc(d)+'</code></td><td>'+esc(domain(d))+'</td></tr>').join('')+(ret!=='V'?'<tr><td><a href="#'+key+'/return">return</a><br><small>'+esc(fid+'-return')+'</small></td><td>'+esc(typ(ret))+'</td><td>'+esc(domain(ret))+'</td></tr>':'')+'</tbody></table></section>'}
if(target){html+='<p><a href="#'+fragment+'">Toate metodele clasei</a></p>'+method(target,Number(methodIndex));}else{html+='<h3>Metode</h3>'+methods.map(method).join('');if(fields.length)html+='<h3>Câmpuri declarate</h3><table><tr><th>Nume</th><th>Tip</th><th>Acces / stocare</th></tr>'+fields.map(f=>'<tr><td>'+esc(f[0])+'</td><td>'+esc(typ(f[1]))+'</td><td>'+esc(flags(f[2]))+' · '+esc(f[3])+'</td></tr>').join('')+'</table>';}
html+='<p><a href="catalog-apk-sqlite.zip">Baza SQLite completă</a> · <a href="FUNCTII.html">Catalogul funcțiilor explicate</a></p>';$('#detail').innerHTML=html;}
async function select(){const bits=decodeURIComponent(location.hash.slice(1)).split('/');if(!/^\d{3}$/.test(bits[0])||!/^\d+$/.test(bits[1]||''))return;const n=++loading;if(loaded!==bits[0]){await new Promise((ok,no)=>{let s=document.createElement('script');s.src='dex-date/'+bits[0]+'.js';s.onload=ok;s.onerror=no;document.head.append(s)});if(n!==loading)return;loaded=bits[0];}const c=window.DEX_CHUNK[Number(bits[1])];if(c)renderClass(c,bits.slice(0,2).join('/'),bits[2],bits[3]);}
$('#search').oninput=()=>{let terms=$('#search').value.trim().toLowerCase().split(/\s+/).filter(Boolean);selected=classes.filter(c=>terms.every(t=>c[0].toLowerCase().includes(t)));page=0;draw()};$('#prev').onclick=()=>{page--;draw()};$('#next').onclick=()=>{page++;draw()};window.addEventListener('hashchange',()=>select().catch(e=>{$('#detail').textContent='Nu se poate încărca segmentul: '+e}));selected=classes;draw();select();window.DEX_UI_READY=true;
})();
